EVENT_LISTENERS:
var elements = document.querySelectorAll("*");
var totalListeners = 0;
for (var i = 0; i < elements.length; i++) {
    var events = getEventListeners(elements[i]);
    for (var event in events) {
        totalListeners += events[event].length;
    }
}
return totalListeners;

CSS_CLASSES:
var classes = document.querySelectorAll('[class]');
var uniqueClasses = new Set();
classes.forEach(function(element) {
    element.classList.forEach(function(className) {
        uniqueClasses.add(className);
    });
});
return(uniqueClasses.size);

EVENT_LISTENERS_INTERACT:
var elements = document.querySelectorAll("*");
    var count = 0;
    for (var i = 0; i < elements.length; i++) {
        var element = elements[i];
        if (element.onclick || element.onmouseover || element.onmouseout || 
            element.onmouseenter || element.onmouseleave || element.onkeydown || 
            element.onkeyup || element.onkeypress || element.onfocus || 
            element.onblur || element.onchange || element.oninput || 
            element.onsubmit || element.ondblclick || element.oncontextmenu || 
            element.onwheel || element.onmousedown || element.onmouseup || 
            element.ontouchstart || element.ontouchend || element.ontouchmove) {
            count++;
        }
    }
    return count;

HTML_TAG_SEQUENCE:
function getTagSequence(element, sequence = []) {
    sequence.push(element.tagName.toLowerCase());
    if (element.children.length > 0) {
        for (let i = 0; i < element.children.length; i++) {
            getTagSequence(element.children[i], sequence);
        }
    }
    return sequence;
}
const rootElement = document.documentElement;
return getTagSequence(rootElement);

CAPTURE_LOGS:
function captureConsoleMessages() {
    var capturedMessages = {
        logs: [],
        errors: [],
        warnings: [],
        infos: [],
        debugs: []
    };

    var originalConsoleLog = console.log;
    console.log = function() {
        capturedMessages.logs.push(Array.from(arguments));
        originalConsoleLog.apply(console, arguments);
    };

    var originalConsoleError = console.error;
    console.error = function() {
        capturedMessages.errors.push(Array.from(arguments));
        originalConsoleError.apply(console, arguments);
    };

    var originalConsoleWarn = console.warn;
    console.warn = function() {
        capturedMessages.warnings.push(Array.from(arguments));
        originalConsoleWarn.apply(console, arguments);
    };

    var originalConsoleInfo = console.info;
    console.info = function() {
        capturedMessages.infos.push(Array.from(arguments));
        originalConsoleInfo.apply(console, arguments);
    };

    var originalConsoleDebug = console.debug || console.log;
    console.debug = function() {
        capturedMessages.debugs.push(Array.from(arguments));
        originalConsoleDebug.apply(console, arguments);
    };

    return capturedMessages;
}

var capturedMessages = captureConsoleMessages();
return capturedMessages;
